script:
card({ name: "Reaction test", icon: 'bolt', permissions: ['sound', 'keyboard'], keys: { Space: 'tap', Enter: 'tap' } });
const words = {
  start: "Start",
  wait: "Wait for green…",
  now: "Tap!",
  early: "Too soon! Try again",
  yours: "{p0} ms",
  best: "Fastest",
  about: "Tap Start, then tap as soon as it turns green.",
};

// The wait is random but the same on every phone.
function init() {
  return { tries: {}, best: {}, last: {}, names: {} };
}

on.tap = (s, args, ctx) => {
  const id = ctx.author;
  s.names[id] = ctx.authorName;
  const t = s.tries[id];
  if (!t) {
    s.tries[id] = { go: ctx.time + 1500 + Math.floor(ctx.random() * 3000) };
    return;
  }
  delete s.tries[id];
  if (ctx.time < t.go) {
    s.last[id] = 'early';
    ctx.sound('buzz', { for: id });
    return;
  }
  const ms = Math.min(ctx.time - t.go, 9999);
  s.last[id] = ms;
  if (!s.best[id] || ms < s.best[id]) {
    s.best[id] = ms;
    ctx.sound('coin', { for: id });
  }
};

function view(s, me, now) {
  const t = s.tries[me.id];
  const last = s.last[me.id];
  let big;
  let label;
  let tone;
  if (t && now < t.go) {
    // Redraw often while waiting, so green shows the moment it's time.
    every(30);
    big = words.wait;
    label = words.wait;
    tone = 'danger';
  } else if (t) {
    big = words.now;
    label = words.now;
    tone = 'success';
  } else {
    big = last === 'early' ? words.early : last ? words.yours.replace('{p0}', last) : words.about;
    label = words.start;
    tone = 'accent';
  }
  const ranks = Object.keys(s.best).sort((a, b) => s.best[a] - s.best[b]).slice(0, 5);
  return column([
    text(big, { size: t || last ? 'large' : undefined, bold: true, align: 'center', tone: t ? tone : undefined }),
    button(label, 'tap', null, { tone, size: 'large', align: 'center' }),
    ranks.length > 0 && divider(),
    ranks.length > 0 && text(words.best, { bold: true }),
    ...ranks.map((id, i) => row([text((i + 1) + '. ' + s.names[id]), badge(words.yours.replace('{p0}', s.best[id]), { tone: i === 0 ? 'success' : undefined })], { align: 'between' })),
  ]);
}
